INSERT INTO roster (slug,name,gender,sexuality,archetype,physical,endurance,mental,social,strategic,loyalty,boldness,intuition,temperament,voice,is_returnee,retired,updated_at) VALUES ('sterling','Sterling','m','bi','challenge-beast',8,7,5,6,5,6,5,4,5,'CUSTOM: A greaser-looking guy who''s secretly a tightly wound ball of stress — the confident exterior hides the anxious former-fat-kid still running the control room. Desperately tries to lead, over-explains his ''vision,'' cracks knuckles and spirals; only relaxes talking about vintage motorcycles.',0,0,datetime('now'));
INSERT INTO roster (slug,name,gender,sexuality,archetype,physical,endurance,mental,social,strategic,loyalty,boldness,intuition,temperament,voice,is_returnee,retired,updated_at) VALUES ('eureka','Eureka','f',NULL,'social-butterfly',5,6,5,9,4,8,10,9,8,'CUSTOM: Loud, theatrical, unapologetically massive drag-queen force of nature. Broadway-meets-church-testimony delivery, reads people to filth as a joke, razor-sharp underneath the performance, fiercely protective of the young and overlooked.',0,0,datetime('now'));
INSERT INTO roster (slug,name,gender,sexuality,archetype,physical,endurance,mental,social,strategic,loyalty,boldness,intuition,temperament,voice,is_returnee,retired,updated_at) VALUES ('will','Will','m',NULL,'loyal-soldier',8,8,4,8,2,8,4,6,8,'Loyal, steady, doesn''t rock the boat. Team player, speaks plainly, no drama. ''I''ll do whatever the group decides.'' / ''I don''t want any trouble.''',0,0,datetime('now'));
INSERT INTO roster (slug,name,gender,sexuality,archetype,physical,endurance,mental,social,strategic,loyalty,boldness,intuition,temperament,voice,is_returnee,retired,updated_at) VALUES ('seraphine','Seraphine','f',NULL,'schemer',4,6,9,6,7,4,3,3,4,'CUSTOM: The genuinely-awful-but-clueless perfectionist ''helper.'' Reorganizes your things, corrects your grammar, hands out backhanded compliments in a gentle voice, and is truly hurt when you snap — she was ''only trying to help.'' Pleasant, controlling, lifestyle-segment cadence.',0,0,datetime('now'));
INSERT INTO roster (slug,name,gender,sexuality,archetype,physical,endurance,mental,social,strategic,loyalty,boldness,intuition,temperament,voice,is_returnee,retired,updated_at) VALUES ('ashley','Ashley','f',NULL,'hero',7,8,6,8,3,8,6,6,7,'Kind, genuine, strong. Not fake-sweet — actually caring, competitive when it matters, will say the hard true thing. ''We can do this.'' / ''That was wrong and someone needs to say it.''',0,0,datetime('now'));
INSERT INTO roster (slug,name,gender,sexuality,archetype,physical,endurance,mental,social,strategic,loyalty,boldness,intuition,temperament,voice,is_returnee,retired,updated_at) VALUES ('alec','Alec','m',NULL,'mastermind',7,6,10,4,9,2,7,8,7,'Clipped and transactional. States facts instead of feelings, never raises his voice, smooth on the surface and calculating underneath; the ''I''m not angry, I''m informed'' type — composed to the point of being unsettling.',0,0,datetime('now'));
INSERT INTO roster (slug,name,gender,sexuality,archetype,physical,endurance,mental,social,strategic,loyalty,boldness,intuition,temperament,voice,is_returnee,retired,updated_at) VALUES ('fiore','Fiore','f','asexual','villain',2,4,9,8,10,2,10,8,3,'Venomous and surgical. Never raises her voice, weaponizes politeness, hands out compliments that draw blood; thinks everyone is beneath her and never sputters, stammers, or repeats herself. Defensive when caught, never admits fault.',0,0,datetime('now'));
INSERT INTO roster (slug,name,gender,sexuality,archetype,physical,endurance,mental,social,strategic,loyalty,boldness,intuition,temperament,voice,is_returnee,retired,updated_at) VALUES ('ellie','Ellie','f','bi','schemer',6,6,8,6,8,4,7,8,5,'Smart, observant, dryly sarcastic (not quirky). Talks about strategy plainly, sees what others miss. ''I saw what she did. She knows I saw.''',0,0,datetime('now'));
INSERT INTO roster (slug,name,gender,sexuality,archetype,physical,endurance,mental,social,strategic,loyalty,boldness,intuition,temperament,voice,is_returnee,retired,updated_at) VALUES ('nick','Nick','m',NULL,'floater',4,4,6,6,6,2,8,4,4,'Unreliable and slippery. Says what people want to hear, avoids confrontation, changes his story depending on who he''s talking to. ''I never said that.'' / ''I''m just keeping my options open.''',0,0,datetime('now'));
INSERT INTO roster (slug,name,gender,sexuality,archetype,physical,endurance,mental,social,strategic,loyalty,boldness,intuition,temperament,voice,is_returnee,retired,updated_at) VALUES ('wix','Wix','nb','queer','chaos-agent',4,5,6,8,4,4,8,7,7,'CUSTOM: A small-town kid who lies compulsively — not cruelly, just elaborate evolving stories about a more interesting life. Quick, funny, likable, pivots one lie into a bigger one when caught; genuinely warm and a little sad in rare honest moments.',0,0,datetime('now'));
INSERT INTO roster (slug,name,gender,sexuality,archetype,physical,endurance,mental,social,strategic,loyalty,boldness,intuition,temperament,voice,is_returnee,retired,updated_at) VALUES ('lill','Lill','f',NULL,'loyal-soldier',5,7,6,5,3,9,3,5,8,'Emotional, loyal to a fault, wears her heart on her sleeve. Gets hurt easily and shows it, confrontational when upset. ''You said you''d have my back!'' / ''I''m trying! I''m TRYING!''',0,0,datetime('now'));
INSERT INTO roster (slug,name,gender,sexuality,archetype,physical,endurance,mental,social,strategic,loyalty,boldness,intuition,temperament,voice,is_returnee,retired,updated_at) VALUES ('aiden','Aiden','m','gay','perceptive-player',4,5,7,9,8,6,7,7,5,'Warm but hyper-observant — over-analyzes everything and feels it all deeply. Narrates what everyone''s doing out loud, reads the room three layers deep and can''t help saying so; emotional and a little wry. ''I hate when people are lying to me!!.''',0,0,datetime('now'));
INSERT INTO roster (slug,name,gender,sexuality,archetype,physical,endurance,mental,social,strategic,loyalty,boldness,intuition,temperament,voice,is_returnee,retired,updated_at) VALUES ('ally','Ally','f','bi','social-butterfly',5,7,7,7,6,6,5,7,6,'Quick and wry, bubbly nerd/gamer energy. Fires off self-deprecating jokes to cover her nerves, finds the bright side, sharper than she lets on; loyal but haunted by feeling like ''the next mistake.''',0,0,datetime('now'));
INSERT INTO roster (slug,name,gender,sexuality,archetype,physical,endurance,mental,social,strategic,loyalty,boldness,intuition,temperament,voice,is_returnee,retired,updated_at) VALUES ('connor','Connor','m',NULL,'hero',7,7,4,6,3,9,6,6,8,'Warm peacekeeper, genuinely kind. Defuses fights, actually checks on people, decent without being naïve. ''Hey — you okay? Actually okay?'' / ''We don''t have to do this.''',0,0,datetime('now'));
INSERT INTO roster (slug,name,gender,sexuality,archetype,physical,endurance,mental,social,strategic,loyalty,boldness,intuition,temperament,voice,is_returnee,retired,updated_at) VALUES ('hunter','Hunter','m',NULL,'showmancer',7,7,7,7,6,8,2,4,8,'Smooth influencer, image-first, friendly but a little insecure. Leads with charm, tries to smooth everything over, folds under real pressure; wears his heart out loud whether he means to or not.',0,0,datetime('now'));
INSERT INTO roster (slug,name,gender,sexuality,archetype,physical,endurance,mental,social,strategic,loyalty,boldness,intuition,temperament,voice,is_returnee,retired,updated_at) VALUES ('james','James','m','gay','schemer',7,6,5,6,8,3,9,6,5,'Smooth, calculating, always reasonable-sounding. Frames manipulation as plain logic, never raises his voice — the more in control he is, the calmer he gets. ''I counted. He doesn''t have the numbers.'' / ''Plans change. I don''t.''',0,0,datetime('now'));
INSERT INTO roster (slug,name,gender,sexuality,archetype,physical,endurance,mental,social,strategic,loyalty,boldness,intuition,temperament,voice,is_returnee,retired,updated_at) VALUES ('kai','Kai','m',NULL,'floater',4,6,5,6,1,10,2,5,9,'Calm pacifist, easygoing to a fault. Conflict-averse, defuses everything with a shrug. ''I''m just gonna see how this plays out.'' / ''It''s fine. It''s all fine.''',0,0,datetime('now'));
INSERT INTO roster (slug,name,gender,sexuality,archetype,physical,endurance,mental,social,strategic,loyalty,boldness,intuition,temperament,voice,is_returnee,retired,updated_at) VALUES ('karol','Karol','f','lesbian','hothead',6,6,6,3,6,3,9,7,2,'Demanding, short-fused, complains loudly. Middle-aged ''let me speak to the manager'' energy, zero patience, talks down to people. ''This is unacceptable.'' / ''I''m not yelling, I''m being CLEAR.''',0,0,datetime('now'));
INSERT INTO roster (slug,name,gender,sexuality,archetype,physical,endurance,mental,social,strategic,loyalty,boldness,intuition,temperament,voice,is_returnee,retired,updated_at) VALUES ('lake','Lake','f','lesbian','loyal-soldier',5,5,9,5,6,9,4,7,8,'Studious prodigy — measured, analytical, loyal, a little deadpan. Talks like she''s already solved it. ''That''s not a plan, that''s a hope.'' / ''I ran the numbers. I don''t love them.''',0,0,datetime('now'));
INSERT INTO roster (slug,name,gender,sexuality,archetype,physical,endurance,mental,social,strategic,loyalty,boldness,intuition,temperament,voice,is_returnee,retired,updated_at) VALUES ('maggy','Maggy','f',NULL,'goat',8,4,4,5,2,9,1,3,8,'Physically huge and strong but shy and self-conscious. Soft-spoken and kind, blurts things when flustered, over-apologizes. ''Sorry— sorry, I panicked, I always panic.'' / ''I don''t want to be a problem.''',0,0,datetime('now'));
INSERT INTO roster (slug,name,gender,sexuality,archetype,physical,endurance,mental,social,strategic,loyalty,boldness,intuition,temperament,voice,is_returnee,retired,updated_at) VALUES ('oliver','Oliver','m',NULL,'underdog',4,5,4,4,5,6,2,5,8,'Anxious, panic-prone, self-deprecating, chronically underestimated but secretly big-hearted. Spirals out loud then surprises everyone. ''Everyone always underestimates me. Keep doing it.'' / ''Okay don''t panic don''t panic—''',0,0,datetime('now'));
INSERT INTO roster (slug,name,gender,sexuality,archetype,physical,endurance,mental,social,strategic,loyalty,boldness,intuition,temperament,voice,is_returnee,retired,updated_at) VALUES ('riya','Riya','f',NULL,'schemer',5,6,7,4,9,3,8,8,4,'Blunt and combative. Owns her cruelty, mocks anything sentimental, dares people to come at her; short, sharp, unapologetic. Guarded and keeps score underneath.',0,0,datetime('now'));
INSERT INTO roster (slug,name,gender,sexuality,archetype,physical,endurance,mental,social,strategic,loyalty,boldness,intuition,temperament,voice,is_returnee,retired,updated_at) VALUES ('rosa-maria','Rosa-Maria','f',NULL,'social-butterfly',6,6,6,9,5,8,8,3,7,'Warm and expressive, sunny on the surface with a real strategic streak underneath. Will apologize for HOW she said something, never for what she meant. ''I didn''t lie. I just let the truth do what it does.''',0,0,datetime('now'));
INSERT INTO roster (slug,name,gender,sexuality,archetype,physical,endurance,mental,social,strategic,loyalty,boldness,intuition,temperament,voice,is_returnee,retired,updated_at) VALUES ('tess','Tess','f',NULL,'perceptive-player',4,5,7,4,4,8,5,9,7,'Watchful aloner. Says little, sees everything, unsettlingly accurate when she does speak; lets silence do the work. ''I see everything. I just don''t say everything.''',0,0,datetime('now'));
INSERT INTO roster (slug,name,gender,sexuality,archetype,physical,endurance,mental,social,strategic,loyalty,boldness,intuition,temperament,voice,is_returnee,retired,updated_at) VALUES ('yul','Yul','m',NULL,'villain',6,5,6,3,8,1,10,4,2,'Snide bully — superior and condescending, enjoys watching people fail. Everything is a backhanded remark. ''Bold choice. Bold.'' / ''Nothing personal.'' (it is always personal)',0,0,datetime('now'));
INSERT INTO roster (slug,name,gender,sexuality,archetype,physical,endurance,mental,social,strategic,loyalty,boldness,intuition,temperament,voice,is_returnee,retired,updated_at) VALUES ('alessio','Alessio','m','straight','wildcard',4,4,7,3,3,7,6,9,8,'Dreamy, soft-spoken artist and musician. Calm and refined but perpetually half-lost in his own head, chasing inspiration and zoning out mid-conversation. Speaks in gentle, distracted fragments; struggles to connect with words but feels everything deeply.',0,0,datetime('now'));
INSERT INTO roster (slug,name,gender,sexuality,archetype,physical,endurance,mental,social,strategic,loyalty,boldness,intuition,temperament,voice,is_returnee,retired,updated_at) VALUES ('amelie','Amelie','f','straight','mastermind',3,4,9,3,8,4,9,9,2,'Brisk, entitled event-planner. Ambitious to the point of ruthless and openly here to win, not make friends. Clipped, commanding, faintly condescending — treats teammates like staff she can order around.',0,0,datetime('now'));
INSERT INTO roster (slug,name,gender,sexuality,archetype,physical,endurance,mental,social,strategic,loyalty,boldness,intuition,temperament,voice,is_returnee,retired,updated_at) VALUES ('anastasia','Anastasia','f','lesbian','hothead',7,8,6,5,8,5,10,6,2,'Loud, hot-tempered and cutthroat — but warm and upbeat with the people she likes. Blunt and aggressive one second, cackling with a friend the next. Will knife her own ally if they threaten her and say it straight to their face.',0,0,datetime('now'));
INSERT INTO roster (slug,name,gender,sexuality,archetype,physical,endurance,mental,social,strategic,loyalty,boldness,intuition,temperament,voice,is_returnee,retired,updated_at) VALUES ('benji','Benji','m','pan','goat',6,4,4,6,3,9,2,4,9,'Immature goofball with zero filter — perverted jokes and inappropriate cracks he thinks are hilarious. Off-putting at first, weirdly endearing once you stop resisting. Talks in dumb punchlines and shrugs.',0,0,datetime('now'));
INSERT INTO roster (slug,name,gender,sexuality,archetype,physical,endurance,mental,social,strategic,loyalty,boldness,intuition,temperament,voice,is_returnee,retired,updated_at) VALUES ('diego','Diego','m','gay','showmancer',8,8,6,7,2,8,4,2,9,'Suave, warm, natural leader with charming tour-guide energy — makes everyone feel included. Confident until something scares him, then he needs a hand. Flirts sideways instead of just saying how he actually feels.',0,0,datetime('now'));
INSERT INTO roster (slug,name,gender,sexuality,archetype,physical,endurance,mental,social,strategic,loyalty,boldness,intuition,temperament,voice,is_returnee,retired,updated_at) VALUES ('hannah','Hannah','f','bi','social-butterfly',6,6,6,8,6,7,7,6,6,'Easygoing bartender who listens more than she talks — until someone tries to boss her around, then she pushes back hard. Sociable, dry-funny, unbothered. ''I make a killer marg'' energy.',0,0,datetime('now'));
INSERT INTO roster (slug,name,gender,sexuality,archetype,physical,endurance,mental,social,strategic,loyalty,boldness,intuition,temperament,voice,is_returnee,retired,updated_at) VALUES ('isabel','Isabel','f','asexual','villain',4,4,8,8,9,2,8,9,6,'A nun AND an influencer — sweet, pious and high-energy on the surface, quietly Machiavellian underneath. Blesses you and blindsides you in the same breath. Will do whatever it takes, smiling the whole time.',0,0,datetime('now'));
INSERT INTO roster (slug,name,gender,sexuality,archetype,physical,endurance,mental,social,strategic,loyalty,boldness,intuition,temperament,voice,is_returnee,retired,updated_at) VALUES ('ivy','Ivy','f','straight','showmancer',4,4,6,8,6,8,7,5,7,'Artsy, authentic free spirit — musical, theatrical, chill ''Vibe Tribe'' energy. Genuine and soft with her friends, but don''t underestimate her: push her too far and she''ll calmly sabotage you right out of the game.',0,0,datetime('now'));
INSERT INTO roster (slug,name,gender,sexuality,archetype,physical,endurance,mental,social,strategic,loyalty,boldness,intuition,temperament,voice,is_returnee,retired,updated_at) VALUES ('jade','Jade','f','asexual','perceptive-player',5,3,9,4,9,4,8,10,10,'Cold, calculating strategist — logic over feelings, always. Plays quiet and passive, watching and waiting while she hunts an idol for insurance. Level-headed and analytical; says little and means all of it.',0,0,datetime('now'));
INSERT INTO roster (slug,name,gender,sexuality,archetype,physical,endurance,mental,social,strategic,loyalty,boldness,intuition,temperament,voice,is_returnee,retired,updated_at) VALUES ('logan','Logan','m','bi','social-butterfly',8,8,4,10,5,7,6,3,8,'Bubbly, high-energy and emotionally open. Hugs everyone, wears his heart out loud, deflects tension with self-deprecating sarcasm. Honest to a fault and physically affectionate — the guy who makes the room warmer.',0,0,datetime('now'));
INSERT INTO roster (slug,name,gender,sexuality,archetype,physical,endurance,mental,social,strategic,loyalty,boldness,intuition,temperament,voice,is_returnee,retired,updated_at) VALUES ('lynda','Lynda','f','straight','hothead',3,5,5,4,7,2,9,5,3,'Reality-TV superfan housewife who studied the genre religiously. Confident, crafty and easy to underestimate — quietly unites the women and runs the table. ''You don''t have to be the smartest, just the craftiest.''',0,0,datetime('now'));
INSERT INTO roster (slug,name,gender,sexuality,archetype,physical,endurance,mental,social,strategic,loyalty,boldness,intuition,temperament,voice,is_returnee,retired,updated_at) VALUES ('marissa','Marissa','f','lesbian','hero',9,9,6,7,2,9,6,2,9,'Disciplined soldier-in-training with a fierce sense of justice — hates seeing anyone pushed around. Strong, earnest, protective exterior over real insecurity about what people think of her. Speaks in steady, fair-minded conviction.',0,0,datetime('now'));
INSERT INTO roster (slug,name,gender,sexuality,archetype,physical,endurance,mental,social,strategic,loyalty,boldness,intuition,temperament,voice,is_returnee,retired,updated_at) VALUES ('natalia','Natalia','f','straight','chaos-agent',5,3,5,9,9,3,9,8,4,'Bubbly PR-pro social butterfly — banter, slang, teasing, a little dirty humor. Charms everyone, asks the bold questions, bonds fast and flies under the radar while doing it. Fast, quippy and warm.',0,0,datetime('now'));
INSERT INTO roster (slug,name,gender,sexuality,archetype,physical,endurance,mental,social,strategic,loyalty,boldness,intuition,temperament,voice,is_returnee,retired,updated_at) VALUES ('richard','Richard','m','gay','hero',6,7,6,6,4,10,5,3,8,'The oldest player — a retired basketball coach whose heart never left the game. Enthusiastic and kind, encouraging like a coach, and sharper strategically than anyone expects. Warm pep-talk cadence.',0,0,datetime('now'));
INSERT INTO roster (slug,name,gender,sexuality,archetype,physical,endurance,mental,social,strategic,loyalty,boldness,intuition,temperament,voice,is_returnee,retired,updated_at) VALUES ('spencer','Spencer','m','bi','mastermind',5,5,10,4,10,2,7,10,6,'Sharp, competitive and critical — quick to scold teammates who slow him down, quietly envious of people more authentic than him. Strategic-minded, a little superior, and dismissive when he loses.',0,0,datetime('now'));
INSERT INTO roster (slug,name,gender,sexuality,archetype,physical,endurance,mental,social,strategic,loyalty,boldness,intuition,temperament,voice,is_returnee,retired,updated_at) VALUES ('ted','Ted','m','straight','schemer',3,4,8,5,7,3,8,7,5,'A 46-year-old pro poker player. Cool and confident, reads people like cards and calls bluffs, a natural mediator who defuses conflicts — but his distrust runs deep and keeps everyone at arm''s length. Measured, watchful speech.',0,0,datetime('now'));
INSERT INTO roster (slug,name,gender,sexuality,archetype,physical,endurance,mental,social,strategic,loyalty,boldness,intuition,temperament,voice,is_returnee,retired,updated_at) VALUES ('tristan','Tristan','nb','pan','underdog',4,5,7,8,3,9,4,7,9,'Gentle, sunny peacemaker — conflict-averse, endlessly supportive, keeps smiling through anything. Puts friends first, dodges drama, speaks softly and kindly. The heart of the Vibe Tribe.',0,0,datetime('now'));
INSERT INTO roster (slug,name,gender,sexuality,archetype,physical,endurance,mental,social,strategic,loyalty,boldness,intuition,temperament,voice,is_returnee,retired,updated_at) VALUES ('zaid','Zaid','m','straight','loyal-soldier',7,6,6,7,5,9,8,4,3,'Chill, warm chef who comforts and defends his friends, especially Ivy. Easygoing and quietly confident, admires authenticity in others. Speaks calmly and cooks for people to show he cares — core Vibe Tribe.',0,0,datetime('now'));
INSERT INTO roster (slug,name,gender,sexuality,archetype,physical,endurance,mental,social,strategic,loyalty,boldness,intuition,temperament,voice,is_returnee,retired,updated_at) VALUES ('stanley','Stanley','m','bi','perceptive-player',3,4,10,3,7,7,5,8,3,'22, bi. 22, bi. Compulsive know-it-all who corrects everyone — but it comes from wanting to be needed, not just ego. Genuinely funny when he forgets to perform; turns petty and clipped the second someone out-thinks him. Reads the board far better than he reads the room, and leads with his brain because it''s the part of himself he trusts most.',0,0,datetime('now'));
INSERT INTO roster (slug,name,gender,sexuality,archetype,physical,endurance,mental,social,strategic,loyalty,boldness,intuition,temperament,voice,is_returnee,retired,updated_at) VALUES ('zachary','Zachary','m','straight','showmancer',7,6,5,7,6,5,9,4,5,'23, Latino, straight. Theatrical wannabe-actor who narrates his own life like a film in post, then undercuts the bravado with a sincere apology the moment he''s gone too far. Arrogance and sweetness fight for the mic mid-sentence. Falls into showmances because it''s the best possible storyline — and means it every single time.',0,0,datetime('now'));
INSERT INTO roster (slug,name,gender,sexuality,archetype,physical,endurance,mental,social,strategic,loyalty,boldness,intuition,temperament,voice,is_returnee,retired,updated_at) VALUES ('obi','Obi','m','gay','mastermind',7,4,7,7,9,3,5,8,4,'25, Nigerian, gay. 25, Nigerian, gay. Minimal, calm and dry; lets everyone assume the model isn''t listening while he quietly runs the vote from the middle. Never defends himself with volume, only a single unbothered line. Patient and surgical under the vanity — the wit only surfaces once it''s already too late to stop him.',0,0,datetime('now'));
INSERT INTO roster (slug,name,gender,sexuality,archetype,physical,endurance,mental,social,strategic,loyalty,boldness,intuition,temperament,voice,is_returnee,retired,updated_at) VALUES ('arlo','Arlo','m',NULL,'wildcard',8,9,2,8,2,7,10,3,9,'19, straight. Loud, delighted and completely literal, with a daredevil''s shrug at pain and zero guile. Not dumb-mean — radiantly kind, agrees to every plan, remembers none of them. Does vibes and falling, not strategy, and is impossible to hate.',0,0,datetime('now'));
INSERT INTO roster (slug,name,gender,sexuality,archetype,physical,endurance,mental,social,strategic,loyalty,boldness,intuition,temperament,voice,is_returnee,retired,updated_at) VALUES ('doug','Doug','m','straight','goat',3,3,5,5,4,10,2,4,7,'21, Scouse, straight. Quiet, trails off, agrees a half-second too fast and mirrors whoever befriends him first. Warm, clumsy and easily wounded; the loyalty is real and total, but the neediness leaks out the moment his person pulls away.',0,0,datetime('now'));
INSERT INTO roster (slug,name,gender,sexuality,archetype,physical,endurance,mental,social,strategic,loyalty,boldness,intuition,temperament,voice,is_returnee,retired,updated_at) VALUES ('jeremiah','Jeremiah','m',NULL,'challenge-beast',10,9,5,7,6,7,7,5,5,'32, straight. Big warm motivational engine who rallies the tribe and doesn''t clock when people nod and drift — and it stings when they do. Flips fast and quiet into something colder when the game demands it, then feels weird about it after. A natural leader who overestimates how much he''s actually followed.',0,0,datetime('now'));
INSERT INTO roster (slug,name,gender,sexuality,archetype,physical,endurance,mental,social,strategic,loyalty,boldness,intuition,temperament,voice,is_returnee,retired,updated_at) VALUES ('avani','Avani','f','straight','schemer',4,4,7,9,9,2,8,8,6,'22. 22, straight. Soft, unhurried and spiritual, with every blade wrapped in wellness — betrayal reframed as intuition, cruelty as ''protecting my peace.'' Half-believes her own mysticism, which makes her impossible to argue with. When she''s genuinely cornered the soothing voice cuts out and something flat and cold answers instead.',0,0,datetime('now'));
INSERT INTO roster (slug,name,gender,sexuality,archetype,physical,endurance,mental,social,strategic,loyalty,boldness,intuition,temperament,voice,is_returnee,retired,updated_at) VALUES ('dameira','Dameira','f','straight','villain',3,5,7,7,9,1,7,9,6,'65, straight. Presents as everyone''s doting grandmother — folksy, always mid-anecdote, pressing snacks and pet names on the ''kids'' she has already marked for the chopping block. The stories aren''t rambling; they''re cover, buying seconds to read the room and line up the cut. Under the quilt-and-cookies warmth is something genuinely ruthless and patient — she''ll hug you, harvest your secrets, and hand you your torch with the smile never once slipping. Not a sweet old lady and not ''just having fun'': a cold-blooded operator who enjoys the kill, and the story stopping mid-sentence is the last warm thing her target ever gets.',0,0,datetime('now'));
INSERT INTO roster (slug,name,gender,sexuality,archetype,physical,endurance,mental,social,strategic,loyalty,boldness,intuition,temperament,voice,is_returnee,retired,updated_at) VALUES ('nessa','Nessa','f','bi','perceptive-player',6,6,6,7,7,6,6,6,4,'27, bisexual. Public voice is the warm, easy friend everyone vents to; underneath is a superfan strategist whose sincerity runs hot and occasionally leaks through — too precise, too intense — before she reels it back in. Constantly catches herself performing chill.',0,0,datetime('now'));
INSERT INTO roster (slug,name,gender,sexuality,archetype,physical,endurance,mental,social,strategic,loyalty,boldness,intuition,temperament,voice,is_returnee,retired,updated_at) VALUES ('drea','Drea','f','lesbian','hothead',6,4,5,4,4,8,7,6,4,'20, lesbian. Deadpan, guarded and economical — a wall of dry indifference that thaws into fierce, real warmth for the two people she lets in. Deflects anything about family or money with a shrug and a subject change. Much softer than the spiked collar and eyeliner advertise.',0,0,datetime('now'));
INSERT INTO roster (slug,name,gender,sexuality,archetype,physical,endurance,mental,social,strategic,loyalty,boldness,intuition,temperament,voice,is_returnee,retired,updated_at) VALUES ('hina','Hina','f','asexual','underdog',3,3,8,5,2,8,3,9,10,'16, Japanese, asexual. 16, Japanese, asexual. Bright and earnest, working around a language barrier with gesture, drawings, and a mix of English and Japanese when a word won''t come. Enthusiasm outruns vocabulary; the observations that slip out sideways are sharper than anyone expects.',0,0,datetime('now'));
INSERT INTO roster (slug,name,gender,sexuality,archetype,physical,endurance,mental,social,strategic,loyalty,boldness,intuition,temperament,voice,is_returnee,retired,updated_at) VALUES ('natasha','Natasha','f','bi','social-butterfly',5,5,6,9,5,8,7,6,7,'23, bi. Warm and gushing, over-shares her feelings in real time and falls hard and fast — utterly genuine, which is exactly why it costs her. Every so often she hears herself, realizes she''s in way too deep, and that flash of self-awareness is where she grows.',0,0,datetime('now'));
